'use strict';
function canDo(key){if(currentUser.role==='supervisor')return true;if(Array.isArray(currentUser.permissions))return currentUser.permissions.includes(key);const base=['cases.view','warehouse.view','plating.view','wire.view','wire.cut','wire.editOwn','wire.photos'];return base.includes(key)||(currentUser.role==='warehouse'&&['warehouse.stock','warehouse.photos','plating.manage','plating.photos','wire.create','wire.edit','wire.delete'].includes(key));}
let permissionProfiles=[],permissionCapabilities={};
async function loadPermissionProfiles(){const r=await apiFetch('/api/permissions'),d=await r.json();if(!r.ok)throw Error(d.error);permissionProfiles=d.items;permissionCapabilities=d.capabilities;}
function permissionDialog(profile){
 modal(profile?'修改自訂權限':'新增自訂權限',field('權限名稱','profileName',profile?.name||'','required maxlength="80"')+'<p class="muted">主管與倉管的補貨狀態權限固定；匯出及管理後台固定只有主管能操作。既有管理區的「管理」包含新增、修改、刪除及排序。</p><div class="permission-options">'+Object.entries(permissionCapabilities).map(([key,label])=>'<label><input type="checkbox" name="capability" value="'+esc(key)+'" '+(profile?.permissions.includes(key)?'checked':'')+'> '+esc(label)+'</label>').join('')+'</div>','儲存權限',async fd=>{await permissionRequest({id:profile?.id,name:String(fd.get('profileName')).trim(),permissions:fd.getAll('capability')});$('#modal').close();renderAdmin();});
}
async function permissionRequest(data,method='POST'){const r=await apiFetch('/api/permissions',{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),d=await r.json();if(!r.ok)throw Error(d.error);await loadPermissionProfiles();addAudit('更新員工權限設定',data.name||'員工排序／移除權限','管理後台 > 員工權限');await saveCloud(state);if(failedCandidate)throw Error('設定已更新，但操作紀錄儲存失敗，請處理上方提示');}
const employeeLoadBeforePermissions=loadEmployees;
loadEmployees=async function(){try{await loadPermissionProfiles();}catch(e){const box=$('#employee-list');if(box)box.textContent=e.message;return;}await employeeLoadBeforePermissions();const box=$('#employee-list');if(!box)return;
 box.querySelectorAll('.employee-row').forEach((row,i)=>{const e=employeesCache[i];const profile=permissionProfiles.find(p=>p.id===e.profileId);if(profile)row.querySelector('small').textContent=e.email+' · '+profile.name+' · '+(e.status==='active'?'啟用':'停用');for(const [label,delta]of [['↑',-1],['↓',1]]){const b=document.createElement('button');b.className='small';b.textContent=label;b.setAttribute('aria-label',e.name+(delta<0?'上移':'下移'));b.disabled=i+delta<0||i+delta>=employeesCache.length;b.onclick=async()=>{b.disabled=true;try{const ids=employeesCache.map(x=>x.id);[ids[i],ids[i+delta]]=[ids[i+delta],ids[i]];await permissionRequest({order:ids});await loadEmployees();}catch(err){toast(err.message);b.disabled=false;}};row.append(b);}});
 const panel=document.createElement('div');panel.id='permission-settings';panel.innerHTML='<h3>自訂權限</h3><p class="muted">設定後，於員工的權限層級選擇「一般員工」，再指定自訂權限。員工重新整理後套用新介面；伺服器權限立即生效。</p><button type="button" id="new-permission">＋ 新增權限</button>'+permissionProfiles.map(p=>'<div class="admin-row"><strong>'+esc(p.name)+'</strong><button type="button" data-profile-edit="'+esc(p.id)+'">修改</button><button type="button" data-profile-delete="'+esc(p.id)+'">刪除</button></div>').join('');$('#permission-settings')?.remove();box.after(panel);$('#new-permission').onclick=()=>permissionDialog();panel.querySelectorAll('[data-profile-edit]').forEach(b=>b.onclick=()=>permissionDialog(permissionProfiles.find(p=>p.id===b.dataset.profileEdit)));panel.querySelectorAll('[data-profile-delete]').forEach(b=>b.onclick=async()=>{if(!await confirmAction('確定刪除此自訂權限？'))return;try{await permissionRequest({id:b.dataset.profileDelete},'DELETE');await loadEmployees();}catch(e){toast(e.message);}});
};
const employeeDialogBeforePermissions=employeeDialog;
employeeDialog=function(id){employeeDialogBeforePermissions(id);const e=employeesCache.find(x=>x.id===id),label=document.createElement('label');label.className='field';label.innerHTML='自訂權限<select name="profileId"><option value="">預設一般員工</option>'+permissionProfiles.map(p=>'<option value="'+esc(p.id)+'" '+(p.id===e?.profileId?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select>';$('#modal select[name="role"]').closest('.form-grid').after(label);const role=$('#modal select[name="role"]');const update=()=>{label.hidden=role.value!=='viewer';label.querySelector('select').disabled=role.value!=='viewer';};role.addEventListener('change',update);update();};
const pagesBeforePermissions=managementPages;
managementPages=function(){return pagesBeforePermissions().filter(p=>!['cases','warehouse','plating','wire'].includes(p.id)||canDo(p.id+'.view'));};
